using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
namespace FrameScout {
 public static class NounImporter {
  static readonly string[] Names={"canonical","name","term","标准名词","名词","名称"},Aliases={"aliases","alias","别称","别名","可接受别称"},Categories={"category","type","类型","分类"};
  static string Key(string s){return s.Trim().Trim('\uFEFF').Replace(" ","").ToLowerInvariant();}
  static string Value(Dictionary<string,object> map,string[] keys){foreach(var pair in map)if(keys.Contains(Key(pair.Key)))return pair.Value is object[]?string.Join("、",((object[])pair.Value).Select(x=>Convert.ToString(x))):Convert.ToString(pair.Value);return "";}
  static void Add(List<Noun> list,string name,string aliases,string category){name=(name??"").Trim().Trim('"','“','”');if(name.Length==0)return;if(name.Length>80||name.Contains('\n'))throw new IOException("名词长度或格式不正确："+name.Substring(0,Math.Min(40,name.Length)));list.Add(new Noun{Canonical=name,Aliases=NormalizeAliases(aliases,name),Category=string.IsNullOrWhiteSpace(category)?"导入":category.Trim()});if(list.Count>50000)throw new IOException("名词超过五万项，请拆分导入。");}
  public static string NormalizeAliases(string text,string name){return string.Join("、",Regex.Split(text??"",@"[、,，;；/\r\n]+").Select(x=>x.Trim()).Where(x=>x.Length>0&&x!=name).Distinct(StringComparer.Ordinal));}
  static string Rtf(string file){string result=null;Exception error=null;var thread=new Thread(()=>{try{using(var stream=File.OpenRead(file)){if(stream.Length>40*1024*1024)throw new IOException("RTF 文件过大。");var document=new FlowDocument();var range=new TextRange(document.ContentStart,document.ContentEnd);range.Load(stream,DataFormats.Rtf);result=range.Text;}}catch(Exception ex){error=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.IsBackground=true;thread.Start();thread.Join();if(error!=null)throw new IOException("RTF 读取失败："+error.Message);return result;}
  public static List<Noun> Read(string file){var list=new List<Noun>();string ext=Path.GetExtension(file).ToLowerInvariant();if(!new[]{".txt",".md",".csv",".tsv",".json",".docx",".rtf"}.Contains(ext))throw new IOException("支持 TXT、MD、CSV、TSV、JSON、DOCX、RTF。");string text=ext==".docx"?SubtitleIO.Script(file):ext==".rtf"?Rtf(file):SubtitleIO.ReadText(file);if(ext==".json")ReadJson(Util.Json().DeserializeObject(text),list,null);else if(ext==".csv"||ext==".tsv")ReadTable(text,ext==".tsv"?'\t':',',list);else ReadLines(text,list);if(list.Count==0)throw new IOException("没有读取到名词，请使用每行一个名词，或标准名词 / 别称 / 类型的表格。");return Merge(new List<Noun>(),list);}
  static void ReadJson(object data,List<Noun> list,string category){var array=data as object[];if(array!=null){foreach(var value in array)ReadJson(value,list,category);return;}var map=data as Dictionary<string,object>;if(map!=null){string name=Value(map,Names);if(name.Length>0){Add(list,name,Value(map,Aliases),Value(map,Categories));return;}object nouns;if(map.TryGetValue("nouns",out nouns)||map.TryGetValue("terms",out nouns)||map.TryGetValue("名词表",out nouns)){ReadJson(nouns,list,category);return;}foreach(var pair in map)if(pair.Value is object[])ReadJson(pair.Value,list,pair.Key);return;}if(data is string)Add(list,(string)data,"",category);}
  static List<string[]> Rows(string text,char separator){var rows=new List<string[]>();var row=new List<string>();var field=new StringBuilder();bool quote=false;for(int i=0;i<text.Length;i++){char c=text[i];if(c=='"'){if(quote&&i+1<text.Length&&text[i+1]=='"'){field.Append('"');i++;}else if(quote||field.ToString().Trim().Length==0)quote=!quote;else field.Append(c);}else if(c==separator&&!quote){row.Add(field.ToString());field.Clear();}else if((c=='\r'||c=='\n')&&!quote){if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;row.Add(field.ToString());field.Clear();if(row.Any(x=>x.Trim().Length>0))rows.Add(row.ToArray());row.Clear();}else field.Append(c);}if(quote)throw new IOException("表格引号未闭合。");row.Add(field.ToString());if(row.Any(x=>x.Trim().Length>0))rows.Add(row.ToArray());return rows;}
  static void ReadTable(string text,char separator,List<Noun> list){var rows=Rows(text,separator);if(rows.Count==0)return;int name=0,alias=1,category=2,start=0;var header=rows[0].Select(Key).ToArray();int found=Array.FindIndex(header,h=>Names.Contains(h));if(found>=0){name=found;alias=Array.FindIndex(header,h=>Aliases.Contains(h));category=Array.FindIndex(header,h=>Categories.Contains(h));start=1;}for(int i=start;i<rows.Count;i++){var row=rows[i];Add(list,Cell(row,name),Cell(row,alias),Cell(row,category));}}
  static string Cell(string[] row,int at){return at>=0&&at<row.Length?row[at].Trim():"";}
  static bool Section(string s){return Regex.IsMatch(s,@"^(人物|人名|角色|地点|地名|场景|组织|道具|专用词|专有名词)(名称|名词|表|列表)?$");}
  static void ReadLines(string text,List<Noun> list){string category="导入";foreach(var raw in text.Replace("\r","").Split('\n')){string line=raw.Trim();if(line.Length==0||line.StartsWith("//")||Regex.IsMatch(line,@"^[-| :]+$"))continue;line=Regex.Replace(line,@"^\s*(#{1,6}\s*|[-*•]\s+|\d+[.、)）]\s*)","").Trim();string clean=line.Trim('【','】','[',']','：',':',' ','*');if(Section(clean)){category=clean;continue;}if(clean=="名词表"||clean=="标准名词"||clean=="名称")continue;var section=Regex.Match(line,@"^(人物|人名|角色|地点|地名|场景|组织|道具|专用词|专有名词)(名称|名词)?[：:]\s*(.+)$");if(section.Success){foreach(var name in Regex.Split(section.Groups[3].Value,@"[、,，;；]+"))Add(list,name,"",section.Groups[1].Value);continue;}if(line.Contains("|")||line.Contains("\t")){var row=line.Trim('|').Split(line.Contains("|")?'|':'\t').Select(x=>x.Trim()).ToArray();if(Names.Contains(Key(row[0])))continue;Add(list,Cell(row,0),Cell(row,1),row.Length>2?Cell(row,2):category);}else foreach(var name in Regex.Split(line,@"[、,，;；]+"))Add(list,name,"",category);}}
  public static List<Noun> Merge(IEnumerable<Noun> existing,IEnumerable<Noun> incoming){var map=new Dictionary<string,Noun>(StringComparer.Ordinal);foreach(var item in existing.Concat(incoming)){if(string.IsNullOrWhiteSpace(item.Canonical))continue;Noun noun;if(!map.TryGetValue(item.Canonical,out noun))map[item.Canonical]=new Noun{Canonical=item.Canonical,Aliases=NormalizeAliases(item.Aliases,item.Canonical),Category=item.Category,Sources=item.Sources==null?new List<NounSource>():item.Sources.ToList()};else{noun.Aliases=NormalizeAliases(noun.Aliases+"、"+item.Aliases,noun.Canonical);if(string.IsNullOrWhiteSpace(noun.Category)||noun.Category=="导入")noun.Category=item.Category;}}return map.Values.ToList();}
 }
 public sealed partial class SubtitlePanel {
  public async Task ImportNounFiles(string[] paths){if(IsBusy){Status("请先等待当前操作完成，再导入名词表。");return;}nounImporting=true;Busy(true);var incoming=new List<Noun>();var errors=new List<string>();int success=0;try{foreach(var file in paths){try{var nouns=await Task.Run(()=>NounImporter.Read(file));incoming.AddRange(nouns);success++;}catch(Exception ex){errors.Add(Path.GetFileName(file)+"："+ex.Message);}}if(closed)return;int before=Nouns.Count;Nouns=NounImporter.Merge(Nouns,incoming);await Task.Run(()=>ScriptEvidence.Enrich(Nouns,script));Get<TextBlock>("NounCount").Text="名词表："+Nouns.Count+" 项";Status("名词导入完成："+success+" 个文件，新增 "+(Nouns.Count-before)+" 项，共 "+Nouns.Count+" 项。"+(errors.Count>0?"部分未导入："+string.Join("；",errors):"同名项与别称已合并，可打开名词表审核。"));NotifyChanged();}finally{nounImporting=false;if(!closed)Busy(cancel!=null);}}
 }
}
